import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_valid_amounts_are_decimal_cents(self):
        self.assertEqual(invoice_amount("12"), Decimal("12.00"))
        self.assertEqual(invoice_amount(" 12.3 "), Decimal("12.30"))
        self.assertEqual(invoice_amount("0.01"), Decimal("0.01"))

    def test_invalid_amounts_are_rejected(self):
        for value in ("", "1.234", "-1.00", "1e2", "NaN", ".50", "1."):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_non_string_amount_is_rejected(self):
        with self.assertRaises(TypeError):
            invoice_amount(1)


if __name__ == "__main__":
    unittest.main()
